      *out++ = data[1];
      return out;
    }
    return copy_str<Char>(data, data + size, out);
  }

  bool should_emit_separator(int remaining, int mark) const {
    if (thousands_sep_.empty()) return false;
    if (remaining <= 0) return false;
    if (mark <= 0) return false;
    if (remaining != mark) return false;
    return true;
  }

  int max_separator_positions(int num_digits) const {
    if (thousands_sep_.empty() || num_digits <= 0) return 0;
    if (grouping_.empty()) return 0;
    int first = first_group_size();
    if (first <= 0) return count_separators(num_digits);
    int estimate = num_digits / first;
    if (estimate < 0) return 0;
    if (estimate > num_digits) return num_digits;
    return estimate;
  }

