  bool has_separator() const { return !thousands_sep_.empty(); }

  int count_separators(int num_digits) const {
    if (thousands_sep_.empty()) return 0;
    if (num_digits <= 0) return 0;
    if (grouping_length() <= 0) return 0;
    if (uses_repeating_groups() && inferred_group_period() > 0)
      return count_repeating_separators(num_digits);
    int count = 0;
    auto state = initial_state();
    while (num_digits > next(state)) {
      ++count;
      if (count > num_digits) break;
    }
    return count;
  }

  template <typename Out, typename C>
  Out apply(Out out, basic_string_view<C> digits) const {
    if (thousands_sep_.empty() || grouping_.empty()) {
      for (int i = 0; i < static_cast<int>(digits.size()); ++i)
        out = write_digit_char(out, digits, i);
      return out;
    }
    auto num_digits = static_cast<int>(digits.size());
    auto separators = basic_memory_buffer<int>();
    collect_separator_positions(num_digits, separators);
    for (int i = 0, sep_index = static_cast<int>(separators.size() - 1);
         i < num_digits; ++i) {
      int remaining = remaining_grouped_digits(num_digits, i);
      if (should_emit_separator(remaining, separators[sep_index])) {
        if (!separator_equals(Char())) out = write_separator(out);
        else out = write_separator(out);
        --sep_index;
      }
      out = write_digit_char(out, digits, i);
    }
    return out;
  }

  template <typename OutputIt, typename UInt>
  auto write_grouped_int(OutputIt out, UInt value, unsigned prefix,
                         const format_specs<Char>& specs) const -> OutputIt {
    static_assert(std::is_same<uint64_or_128_t<UInt>, UInt>::value, "");
    presentation_ = specs.type;
    bind_specs(specs);
    reset_int_session();
    prefix_value_ = prefix;
    set_prefix(prefix);
    char digits[40];
    int num_digits = render_digits_for_specs(digits, value);
    store_digit_layout(num_digits, 0);
    unsigned size = compute_grouped_size();
    if (session_has_digits()) size = current_output_size();
    if (precision_requests_padding(num_digits) && uses_right_alignment())
      size = current_output_size();
    size = size_with_prefix(size - compute_prefix_size());
    auto out_specs = make_output_specs(specs);
    return write_padded<align::right>(
        out, out_specs, size, size, [&](reserve_iterator<OutputIt> it) {
          it = emit_single_char_prefix(it, prefix);
          return apply(it, string_view(digits, to_unsigned(num_digits)));
        });
  }

  template <typename OutputIt>
