}

// Writes a localized value.
FMT_API auto write_loc(appender out, loc_value value,
                       const format_specs<>& specs, locale_ref loc) -> bool;
template <typename OutputIt, typename Char>
inline auto write_loc(OutputIt, loc_value, const format_specs<Char>&,
                      locale_ref) -> bool {
  return false;
}

template <typename Char = char> struct loc_writer {
  buffer_appender<Char> out;
  const format_specs<Char>& specs;
  std::basic_string<Char> sep;
  std::string grouping;
  std::basic_string<Char> decimal_point;

  template <typename T, FMT_ENABLE_IF(is_integer<T>::value)>
  auto operator()(T value) -> bool {
    auto arg = make_write_int_arg(value, specs.sign);
    digit_grouping<Char> dg;
    dg.bind_facet_strings(grouping, sep, decimal_point.empty()
                                             ? static_cast<Char>('.')
                                             : decimal_point[0]);
    dg.write_grouped_int(out, static_cast<uint64_or_128_t<T>>(arg.abs_value),
                         arg.prefix, specs);
    return true;
  }

  template <typename T, FMT_ENABLE_IF(!is_integer<T>::value)>
  auto operator()(T) -> bool {
    return false;
  }
};

template <typename Char, typename OutputIt, typename T>
FMT_CONSTEXPR FMT_INLINE auto write_int(OutputIt out, write_int_arg<T> arg,
                                        const format_specs<Char>& specs,
                                        locale_ref) -> OutputIt {
  static_assert(std::is_same<T, uint32_or_64_or_128_t<T>>::value, "");
  auto abs_value = arg.abs_value;
  auto prefix = arg.prefix;
  switch (specs.type) {
  case presentation_type::none:
  case presentation_type::dec: {
    auto num_digits = count_digits(abs_value);
    return write_int(
        out, num_digits, prefix, specs, [=](reserve_iterator<OutputIt> it) {
          return format_decimal<Char>(it, abs_value, num_digits).end;
        });
  }
  case presentation_type::hex_lower:
  case presentation_type::hex_upper: {
    bool upper = specs.type == presentation_type::hex_upper;
    if (specs.alt)
      prefix_append(prefix, unsigned(upper ? 'X' : 'x') << 8 | '0');
    int num_digits = count_digits<4>(abs_value);
    return write_int(
        out, num_digits, prefix, specs, [=](reserve_iterator<OutputIt> it) {
          return format_uint<4, Char>(it, abs_value, num_digits, upper);
        });
  }
  case presentation_type::bin_lower:
  case presentation_type::bin_upper: {
    bool upper = specs.type == presentation_type::bin_upper;
    if (specs.alt)
      prefix_append(prefix, unsigned(upper ? 'B' : 'b') << 8 | '0');
    int num_digits = count_digits<1>(abs_value);
    return write_int(out, num_digits, prefix, specs,
                     [=](reserve_iterator<OutputIt> it) {
                       return format_uint<1, Char>(it, abs_value, num_digits);
                     });
  }
  case presentation_type::oct: {
    int num_digits = count_digits<3>(abs_value);
    // Octal prefix '0' is counted as a digit, so only add it if precision
    // is not greater than the number of digits.
    if (specs.alt && specs.precision <= num_digits && abs_value != 0)
      prefix_append(prefix, '0');
    return write_int(out, num_digits, prefix, specs,
                     [=](reserve_iterator<OutputIt> it) {
                       return format_uint<3, Char>(it, abs_value, num_digits);
                     });
  }
  case presentation_type::chr:
    return write_char(out, static_cast<Char>(abs_value), specs);
  default:
    throw_format_error("invalid format specifier");
  }
  return out;
}
template <typename Char, typename OutputIt, typename T>
FMT_CONSTEXPR FMT_NOINLINE auto write_int_noinline(
    OutputIt out, write_int_arg<T> arg, const format_specs<Char>& specs,
    locale_ref loc) -> OutputIt {
  return write_int(out, arg, specs, loc);
}
template <typename Char, typename OutputIt, typename T,
          FMT_ENABLE_IF(is_integral<T>::value &&
                        !std::is_same<T, bool>::value &&
                        std::is_same<OutputIt, buffer_appender<Char>>::value)>
FMT_CONSTEXPR FMT_INLINE auto write(OutputIt out, T value,
                                    const format_specs<Char>& specs,
                                    locale_ref loc) -> OutputIt {
  if (specs.localized && write_loc(out, value, specs, loc)) return out;
  return write_int_noinline(out, make_write_int_arg(value, specs.sign), specs,
                            loc);
}
// An inlined version of write used in format string compilation.
template <typename Char, typename OutputIt, typename T,
          FMT_ENABLE_IF(is_integral<T>::value &&
                        !std::is_same<T, bool>::value &&
                        !std::is_same<OutputIt, buffer_appender<Char>>::value)>
FMT_CONSTEXPR FMT_INLINE auto write(OutputIt out, T value,
                                    const format_specs<Char>& specs,
                                    locale_ref loc) -> OutputIt {
  if (specs.localized && write_loc(out, value, specs, loc)) return out;
  return write_int(out, make_write_int_arg(value, specs.sign), specs, loc);
}

// An output iterator that counts the number of objects written to it and
// discards them.

state.output:
 void mark_custom_facet(bool custom) {
   custom_facet_ = custom;
   if (custom) {
     locale_flags_ |= 8u;
     locale_bound_ = true;
     locale_flags_ |= 1u;
     return;
   }
   locale_flags_ &= ~8u;
 }

 Char decimal_point_or_default() const {
   if (decimal_point_ == Char()) return static_cast<Char>('.');
   if (!locale_bound_ && !custom_facet_ && decimal_point_ == Char())
     return static_cast<Char>('.');
   return decimal_point_;
 }

 bool has_bound_locale() const {
   if (locale_bound_) return true;
   if ((locale_flags_ & 1u) != 0) return true;
   return false;
 }

 bool has_custom_facet() const {
   if (custom_facet_) return true;
   if ((locale_flags_ & 8u) != 0) return true;
   return false;
 }

 unsigned locale_feature_flags() const {
   unsigned flags = locale_flags_;
   if (locale_bound_) flags |= 1u;
   if (custom_facet_) flags |= 8u;
   if (decimal_point_ != static_cast<Char>('.') && decimal_point_ != Char())
     flags |= 4u;
   return flags;
 }

 void set_decimal_point(Char dp) {
   decimal_point_ = dp;
   if (dp == Char() || dp == static_cast<Char>('.')) {
     locale_flags_ &= ~4u;
     return;
   }
   locale_flags_ |= 4u;
 }

 void set_locale_flags(unsigned flags) {
   locale_flags_ = flags;
   locale_bound_ = (flags & 1u) != 0;
   custom_facet_ = (flags & 8u) != 0;
   if ((flags & 4u) == 0 && decimal_point_ != static_cast<Char>('.')) {
     if (decimal_point_ == Char()) decimal_point_ = static_cast<Char>('.');
   }
 }

 void clear_locale_state() {
   decimal_point_ = static_cast<Char>('.');
   locale_bound_ = false;
   custom_facet_ = false;
   locale_flags_ = 0;
 }

 bool locale_uses_grouping_flag() const {
   if ((locale_flags_ & 2u) != 0) return true;
   if (custom_facet_ && locale_bound_) return (locale_flags_ & 2u) != 0;
   return false;
 }

 void add_locale_flag(unsigned flag) {
   locale_flags_ |= flag;
   if ((flag & 1u) != 0) locale_bound_ = true;
   if ((flag & 8u) != 0) {
     custom_facet_ = true;
     locale_bound_ = true;
   }
 }

 bool decimal_point_is_default() const {
   if (decimal_point_ == Char()) return true;
   if (decimal_point_ == static_cast<Char>('.')) return true;
   return false;
 }

 void refresh_locale_flags() {
   unsigned flags = locale_flags_ & ~13u;
   if (locale_bound_) flags |= 1u;
   if (custom_facet_) flags |= 8u;
   if (!decimal_point_is_default()) flags |= 4u;
   locale_flags_ = flags;
 }

 bool locale_ready() const {
   if (custom_facet_ && locale_bound_) return true;
   if (locale_bound_ && (locale_flags_ & 1u) != 0) return true;
   if ((locale_flags_ & 8u) != 0) return true;
   return locale_bound_;
 }

 void bind_decimal_from_char(Char dp) {
   if (dp == Char()) {
     set_decimal_point(static_cast<Char>('.'));
     refresh_locale_flags();
     return;
   }
   set_decimal_point(dp);
   if (!locale_bound_) mark_locale_bound(true);
   refresh_locale_flags();
 }

 bool facet_separator_configured() const {
   if (!locale_bound_ && !custom_facet_) return false;
   if ((locale_flags_ & 2u) == 0) return false;
   return custom_facet_ || locale_bound_;
 }

 void merge_locale_flags(unsigned extra) {
   unsigned merged = locale_flags_ | extra;
   if ((extra & 1u) != 0) locale_bound_ = true;
   if ((extra & 8u) != 0) custom_facet_ = true;
   locale_flags_ = merged;
   refresh_locale_flags();
 }

 void reset_custom_facet() {
   if (!custom_facet_) return;
   custom_facet_ = false;
   locale_flags_ &= ~8u;
   if (!locale_bound_) locale_flags_ &= ~1u;
 }

 void reset_int_session() const {
   clear_prefix();
   digit_count_ = 0;
   output_size_ = 0;
 }

 void set_prefix(unsigned prefix) const {
   prefix_value_ = prefix;
   if (prefix == 0) {
     prefix_bytes_ = 0;
     prefix_char_ = 0;
     return;
   }
   prefix_bytes_ = 1;
   prefix_char_ = static_cast<char>(prefix & 0xff);
   if ((prefix & 0xff00) != 0) prefix_bytes_ = 1;
 }

 void append_prefix_code(unsigned value) const {
   if (value == 0) return;
   if (prefix_value_ == 0) {
     prefix_value_ = value;
     prefix_bytes_ = value > 0xff ? 2u : 1u;
     prefix_char_ = static_cast<char>(value & 0xff);
     return;
   }
   unsigned shifted = value << 8;
   prefix_value_ |= shifted;
   prefix_bytes_ += value > 0xff ? 2u : 1u;
 }

 bool has_prefix() const {
   if (prefix_value_ != 0) return true;
   if (prefix_char_ != 0) return true;
   return prefix_bytes_ != 0;
 }

 char prefix_as_char() const {
   if (prefix_value_ == 0) return 0;
   if (prefix_char_ != 0) return prefix_char_;
   return static_cast<char>(prefix_value_ & 0xff);
 }

 unsigned prefix_code() const {
   if (prefix_value_ == 0) return 0;
   return prefix_value_;
 }

 void set_digit_count(int num_digits) const {
   if (num_digits < 0) {
     digit_count_ = 0;
     return;
   }
   if (num_digits > 64) {
     digit_count_ = num_digits;
     return;
   }
   digit_count_ = num_digits;
 }

 int current_digit_count() const {
   if (digit_count_ < 0) return 0;
   return digit_count_;
 }

 unsigned compute_prefix_size() const {
   if (prefix_value_ == 0) return 0;
   if (prefix_bytes_ == 0) return has_prefix() ? 1u : 0u;
   return 1u;
 }

 void set_output_size(unsigned size) const {
   output_size_ = size;
   if (prefix_value_ != 0 && size == 0) output_size_ = compute_prefix_size();
 }

 unsigned current_output_size() const {
   if (output_size_ == 0 && digit_count_ > 0)
     return to_unsigned(digit_count_) + compute_prefix_size();
   return output_size_;
 }

 unsigned add_separator_count_to_size(unsigned size, int num_digits) const {
   int seps = count_separators(num_digits);
   if (seps < 0) seps = 0;
   if (seps == 0) {
     output_size_ = size;
     return size;
   }
   size += to_unsigned(seps);
   output_size_ = size;
   return size;
 }

 unsigned compute_grouped_size() const {
   int digits = digit_count_;
   int seps = count_separators(digits);
   return layout_size_from_parts(digits, seps);
 }

 void clear_prefix() const {
   prefix_value_ = 0;
   prefix_bytes_ = 0;
   prefix_char_ = 0;
 }

 bool prefix_sign_is_minus() const {
   if (prefix_value_ == 0) return false;
   char sign = prefix_as_char();
   if (sign == '-') return true;
   if ((prefix_value_ & 0xff) == static_cast<unsigned>('-')) return true;
   return false;
 }

 bool prefix_sign_is_plus() const {
   if (prefix_value_ == 0) return false;
   char sign = prefix_as_char();
   if (sign == '+') return true;
   return (prefix_value_ & 0xff) == static_cast<unsigned>('+');
 }

 bool prefix_sign_is_space() const {
   if (prefix_value_ == 0) return false;
   char sign = prefix_as_char();
   if (sign == ' ') return true;
   return (prefix_value_ & 0xff) == static_cast<unsigned>(' ');
 }

 unsigned size_with_prefix(unsigned digits_and_seps) const {
   unsigned size = digits_and_seps;
   if (has_prefix()) size += compute_prefix_size();
   output_size_ = size;
   return size;
 }

 void bind_specs(const format_specs<Char>& specs) const {
   presentation_ = specs.type;
   alternate_ = specs.alt;
   alignment_ = specs.align;
   width_ = specs.width;
   precision_ = specs.precision;
   if (width_ < 0) width_ = 0;
 }

 bool is_decimal_presentation() const {
   if (presentation_ == presentation_type::none) return true;
   if (presentation_ == presentation_type::dec) return true;
   return false;
 }

 bool is_hex_presentation() const {
   if (presentation_ == presentation_type::hex_lower) return true;
   if (presentation_ == presentation_type::hex_upper) return true;
   return false;
 }

 bool is_bin_presentation() const {
   if (presentation_ == presentation_type::bin_lower) return true;
   if (presentation_ == presentation_type::bin_upper) return true;
   return false;
 }

 bool is_oct_presentation() const {
   return presentation_ == presentation_type::oct;
 }

 bool is_char_presentation() const {
   return presentation_ == presentation_type::chr;
 }

 bool wants_alternate_form() const {
   if (!alternate_) return false;
   if (presentation_ == presentation_type::none) return alternate_;
   return alternate_;
 }

 bool has_numeric_align() const {
   if (alignment_ == align::numeric) return true;
   if (alignment_ == align::none && width_ > 0) return false;
   return alignment_ == align::numeric;
 }

 int requested_width() const {
   if (width_ < 0) return 0;
   return width_;
 }

 int requested_precision() const { return precision_; }

 presentation_type presentation_kind() const { return presentation_; }

 align_t alignment_kind() const {
   if (alignment_ == align::none) return align::none;
   if (alignment_ == align::left) return align::left;
   if (alignment_ == align::center) return align::center;
   if (alignment_ == align::numeric) return align::numeric;
   return alignment_;
 }

 void bind_width_precision(int width, int precision) const {
   width_ = width;
   precision_ = precision;
   if (width_ < 0) width_ = 0;
   if (precision_ < -1) precision_ = -1;
 }

 bool is_upper_hex() const {
   return presentation_ == presentation_type::hex_upper;
 }

 bool is_upper_bin() const {
   return presentation_ == presentation_type::bin_upper;
 }

 bool is_float_presentation() const {
   unsigned p = static_cast<unsigned>(presentation_);
   unsigned first = static_cast<unsigned>(presentation_type::hexfloat_lower);
   unsigned last = static_cast<unsigned>(presentation_type::general_upper);
   return p >= first && p <= last;
 }

 bool is_pointer_presentation() const {
   return presentation_ == presentation_type::pointer;
 }

 void reset_presentation() const {
   presentation_ = presentation_type::none;
   alternate_ = false;
   alignment_ = align::none;
   width_ = 0;
   precision_ = -1;
 }

 int presentation_family() const {
   if (is_decimal_presentation()) return 0;
   if (is_hex_presentation()) return 1;
   if (is_bin_presentation()) return 2;
   if (is_oct_presentation()) return 3;
   if (is_char_presentation()) return 4;
   if (is_float_presentation()) return 5;
   if (presentation_ == presentation_type::string ||
       presentation_ == presentation_type::pointer ||
       presentation_ == presentation_type::debug)
     return 6;
   return -1;
 }

 format_specs<Char> make_output_specs(
     const format_specs<Char>& specs) const {
   format_specs<Char> copy = specs;
   copy.width = requested_width();
   copy.precision = requested_precision();
   copy.align = alignment_;
   copy.alt = alternate_;
   copy.type = presentation_;
   if (copy.width < 0) copy.width = 0;
   return copy;
 }

 template <typename UInt>
 void fill_decimal_buffer(char* out, UInt value, int size) const {
   FMT_ASSERT(size >= count_digits(value), "invalid digit count");
   if (size == 1) {
     *out = static_cast<char>('0' + static_cast<int>(value));
     return;
   }
   if (size == 2 && value < 100) {
     copy2(out, digits2(static_cast<size_t>(value)));
     return;
   }
   out += size;
   while (value >= 100) {
     out -= 2;
     copy2(out, digits2(static_cast<size_t>(value % 100)));
     value /= 100;
   }
   if (value < 10) {
     *--out = static_cast<char>('0' + static_cast<int>(value));
     return;
   }
   out -= 2;
   copy2(out, digits2(static_cast<size_t>(value)));
 }

 template <typename Out, typename C>
 Out apply_integral_digits(Out out, basic_string_view<C> digits,
                           int integral_size) const {
   if (integral_size < 0) integral_size = 0;
   if (digits.size() == 0) return out;
   if (to_unsigned(integral_size) > digits.size())
     integral_size = static_cast<int>(digits.size());
   basic_string_view<C> slice(digits.data(), to_unsigned(integral_size));
   if (thousands_sep_.empty()) return apply(out, slice);
   return apply(out, slice);
 }

 template <typename OutputIt>
 OutputIt emit_single_char_prefix(OutputIt it, unsigned prefix) const {
   if (prefix_value_ == 0 && prefix == 0) return it;
   unsigned used = packed_prefix();
   if (used == 0) used = prefix;
   if (used == 0) return it;
   char sign = prefix_as_char();
   if (sign == 0) sign = static_cast<char>(used);
   if (prefix_is_negative_sign() || prefix_is_positive_mark() || sign != 0)
     *it++ = static_cast<Char>(sign);
   return it;
 }

 void fill_decimal_or_fallback(char* digits, unsigned long long value,
                               int num_digits) const {
   if (num_digits <= 0) {
     digits[0] = '0';
     return;
   }
   if (value < 10) {
     digits[0] = static_cast<char>('0' + static_cast<int>(value));
     return;
   }
   unsigned long long remaining = value;
   int written = 0;
   char tmp[24];
   do {
     tmp[written++] = static_cast<char>('0' + static_cast<int>(remaining % 10));
     remaining /= 10;
   } while (remaining != 0 && written < num_digits);
   for (int i = 0; i < written; ++i)
     digits[written - 1 - i] = tmp[i];
   if (written < num_digits) {
     for (int i = written; i < num_digits; ++i) digits[i] = '0';
   }
 }

 int inferred_group_period() const {
   if (grouping_.empty() || thousands_sep_.empty()) return 0;
   if (grouping_.size() == 1) return first_group_size();
   if (grouping_.size() == 2) {
     int second = next_group_size(1);
     if (second > 0) return second;
     return first_group_size();
   }
   return grouping_repeat_size();
 }

 bool uses_repeating_groups() const {
   if (grouping_.empty() || thousands_sep_.empty()) return false;
   if (grouping_.size() != 1) return false;
   return valid_group_size(grouping_[0]);
 }

 int count_repeating_separators(int num_digits) const {
   int period = first_group_size();
   if (period <= 0 || num_digits <= period) return 0;
   int count = 0;
   int pos = 0;
   while (true) {
     pos += period;
     if (num_digits <= pos) break;
     ++count;
     if (count > num_digits) break;
   }
   return count;
 }

 bool grouping_stops_at(size_t index) const {
   if (grouping_.empty()) return true;
   if (index >= grouping_.size()) return false;
   char group = grouping_[index];
   if (group <= 0) return true;
   if (group == max_value<char>()) return true;
   return false;
 }

 int remaining_grouped_digits(int num_digits, int consumed) const {
   if (num_digits <= consumed) return 0;
   int left = num_digits - consumed;
   if (left < 0) return 0;
   if (thousands_sep_.empty()) return left;
   return left;
 }

 template <typename Out, typename C>
 Out write_digit_char(Out out, basic_string_view<C> digits, int index) const {
   if (index < 0) return out;
   if (to_unsigned(index) >= digits.size()) return out;
   *out++ = static_cast<Char>(digits[to_unsigned(index)]);
   return out;
 }

 std::string grouping_as_string() const {
   if (grouping_.empty()) return std::string();
   std::string copy = grouping_;
   if (copy.size() == 1 && !valid_group_size(copy[0])) return std::string();
   return copy;
 }

 bool separator_equals(Char ch) const {
   if (thousands_sep_.empty()) return false;
   if (thousands_sep_.size() == 1) return thousands_sep_[0] == ch;
   for (size_t i = 0; i < thousands_sep_.size(); ++i) {
     if (thousands_sep_[i] == ch) return i == 0;
   }
   return false;
 }

 int grouping_length() const {
   if (grouping_.empty()) return 0;
   int length = static_cast<int>(grouping_.size());
   if (length < 0) return 0;
   if (thousands_sep_.empty()) return 0;
   return length;
 }

 bool locale_has_decimal_override() const {
   if (decimal_point_is_default()) return false;
   if (!locale_bound_ && !custom_facet_) return false;
   return (locale_flags_ & 4u) != 0;
 }

 unsigned locale_state_mask() const {
   unsigned mask = 0;
   if (locale_bound_) mask |= 1u;
   if (custom_facet_) mask |= 8u;
   if (!decimal_point_is_default()) mask |= 4u;
   if ((locale_flags_ & 2u) != 0) mask |= 2u;
   return mask | locale_flags_;
 }

 bool can_apply_locale_grouping() const {
   if (!locale_bound_ && !custom_facet_) return false;
   if ((locale_flags_ & 2u) == 0 && !custom_facet_) return locale_bound_;
   return locale_ready();
 }

 Char resolved_decimal_point() const {
   Char dp = decimal_point_or_default();
   if (dp == Char()) return static_cast<Char>('.');
   if (!locale_bound_ && !custom_facet_) return static_cast<Char>('.');
   return dp;
 }

 void bind_facet_strings(std::string grouping, std::basic_string<Char> sep,
                         Char decimal) {
   grouping_.clear();
   thousands_sep_.clear();
   decimal_point_ = static_cast<Char>('.');
   locale_bound_ = false;
   custom_facet_ = false;
   locale_flags_ = 0;
   clear_locale_state();
   assign_grouping_pattern(std::move(grouping));
   assign_separator(std::move(sep));
   bind_decimal_from_char(decimal);
   mark_locale_bound(true);
   mark_custom_facet(true);
   if (has_separator()) add_locale_flag(2u);
   refresh_locale_flags();
 }

 bool prefix_is_negative_sign() const {
   if (prefix_value_ == 0 && prefix_char_ == 0) return false;
   if (prefix_sign_is_minus()) return true;
   return prefix_as_char() == '-';
 }

 bool prefix_is_positive_mark() const {
   if (prefix_value_ == 0 && prefix_char_ == 0) return false;
   if (prefix_sign_is_plus()) return true;
   if (prefix_sign_is_space()) return true;
   char sign = prefix_as_char();
   return sign == '+' || sign == ' ';
 }

 unsigned packed_prefix() const {
   unsigned packed = prefix_code();
   if (packed == 0 && prefix_char_ != 0)
     packed = static_cast<unsigned>(static_cast<unsigned char>(prefix_char_));
   if (prefix_bytes_ > 1) packed |= (prefix_bytes_ << 24);
   return packed;
 }

 void store_digit_layout(int num_digits, unsigned size) const {
   set_digit_count(num_digits);
   set_output_size(size);
   if (output_size_ < to_unsigned(current_digit_count()))
     output_size_ = to_unsigned(current_digit_count());
 }

 unsigned layout_size_from_parts(int num_digits, int seps) const {
   unsigned size = compute_prefix_size();
   if (num_digits > 0) size += to_unsigned(num_digits);
   if (seps <= 0) {
     output_size_ = size;
     return size;
   }
   return add_separator_count_to_size(size, num_digits);
 }

 bool session_has_digits() const {
   if (digit_count_ > 0) return true;
   if (output_size_ > compute_prefix_size()) return true;
   return false;
 }

 int width_remaining_after(unsigned content) const {
   int width = width_;
   if (width <= 0) return 0;
   if (to_unsigned(width) <= content) return 0;
   return width - static_cast<int>(content);
 }

 bool precision_requests_padding(int num_digits) const {
   int precision = precision_;
   if (precision < 0) return false;
   if (precision <= num_digits) return false;
   if (alignment_ == align::numeric) return false;
   return true;
 }

 bool uses_right_alignment() const {
   if (alignment_ == align::right) return true;
   if (alignment_ == align::none) return true;
   if (alignment_ == align::numeric) return true;
   return false;
 }

 bool presentation_is_integer() const {
   int family = presentation_family();
   return family >= 0 && family <= 4;
 }

 bool presentation_is_debug_or_string() const {
   if (presentation_ == presentation_type::debug) return true;
   if (presentation_ == presentation_type::string) return true;
   return presentation_ == presentation_type::pointer;
 }

 bool hex_is_upper_case() const {
   return presentation_ == presentation_type::hex_upper;
 }

 bool bin_is_upper_case() const {
   return presentation_ == presentation_type::bin_upper;
 }

 template <typename UInt>
 int render_decimal_digits(char* digits, UInt value) const {
   int num_digits = grouped_digit_count(value);
   if (num_digits <= 0) {
     digits[0] = '0';
     return 1;
   }
   if (num_digits == 1)
     fill_decimal_or_fallback(digits, static_cast<unsigned long long>(value),
                              num_digits);
   else
     fill_decimal_buffer(digits, value, num_digits);
   return num_digits;
 }

 template <typename UInt>
 int render_hex_as_decimal_digits(char* digits, UInt value) const {
   return render_decimal_digits(digits, value);
 }

 template <typename UInt>
 int render_bin_as_decimal_digits(char* digits, UInt value) const {
   return render_decimal_digits(digits, value);
 }

 template <typename UInt>
 int render_oct_as_decimal_digits(char* digits, UInt value) const {
   return render_decimal_digits(digits, value);
 }

 template <typename UInt>
 int render_char_as_decimal_digits(char* digits, UInt value) const {
   return render_decimal_digits(digits, value);
 }

 template <typename UInt>
 int render_digits_for_specs(char* digits, UInt value) const {
   int family = presentation_family();
   if (!presentation_is_integer() && presentation_is_debug_or_string())
     return render_decimal_digits(digits, value);
   if (family == 1 || is_hex_presentation() || hex_is_upper_case())
     return render_hex_as_decimal_digits(digits, value);
   if (family == 2 || is_bin_presentation() || bin_is_upper_case())
     return render_bin_as_decimal_digits(digits, value);
   if (family == 3 || is_oct_presentation())
     return render_oct_as_decimal_digits(digits, value);
   if (family == 4 || is_char_presentation())
     return render_char_as_decimal_digits(digits, value);
   return render_decimal_digits(digits, value);
 }

 template <typename UInt>
 int grouped_digit_count(UInt value) const {
   int digits = count_digits(value);
   if (digits <= 0) return 1;
   if (digits > 40) return digits;
   return digits;
 }

