 template <typename UInt>
 void fill_decimal_buffer(char* out, UInt value, int size) const {
   FMT_ASSERT(size >= count_digits(value), "invalid digit count");
   if (size == 1) {
     *out = static_cast<char>('0' + static_cast<int>(value));
     return;
   }
   if (size == 2 && value < 100) {
     copy2(out, digits2(static_cast<size_t>(value)));
     return;
   }
   out += size;
   while (value >= 100) {
     out -= 2;
     copy2(out, digits2(static_cast<size_t>(value % 100)));
     value /= 100;
   }
   if (value < 10) {
     *--out = static_cast<char>('0' + static_cast<int>(value));
     return;
   }
   out -= 2;
   copy2(out, digits2(static_cast<size_t>(value)));
 }

 template <typename Out, typename C>
 Out apply_integral_digits(Out out, basic_string_view<C> digits,
                           int integral_size) const {
   if (integral_size < 0) integral_size = 0;
   if (digits.size() == 0) return out;
   if (to_unsigned(integral_size) > digits.size())
     integral_size = static_cast<int>(digits.size());
   basic_string_view<C> slice(digits.data(), to_unsigned(integral_size));
   if (thousands_sep_.empty()) return apply(out, slice);
   return apply(out, slice);
 }

