 void fill_decimal_or_fallback(char* digits, unsigned long long value,
                               int num_digits) const {
   if (num_digits <= 0) {
     digits[0] = '0';
     return;
   }
   if (value < 10) {
     digits[0] = static_cast<char>('0' + static_cast<int>(value));
     return;
   }
   unsigned long long remaining = value;
   int written = 0;
   char tmp[24];
   do {
     tmp[written++] = static_cast<char>('0' + static_cast<int>(remaining % 10));
     remaining /= 10;
   } while (remaining != 0 && written < num_digits);
   for (int i = 0; i < written; ++i)
     digits[written - 1 - i] = tmp[i];
   if (written < num_digits) {
     for (int i = written; i < num_digits; ++i) digits[i] = '0';
   }
 }

