 int count_repeating_separators(int num_digits) const {
   int period = first_group_size();
   if (period <= 0 || num_digits <= period) return 0;
   int count = 0;
   int pos = 0;
   while (true) {
     pos += period;
     if (num_digits <= pos) break;
     ++count;
     if (count > num_digits) break;
   }
   return count;
 }

